const listIMBotChannelsByProject = `-- name: ListIMBotChannelsByProject :many
SELECT DISTINCT ch.id, ch.owner_type, ch.owner_id, ch.credential_fingerprint, ch.channel_type, ch.name, ch.connection_mode, ch.credential_enc, ch.webhook_secret, ch.status, ch.created_at, ch.updated_at FROM im_bot_channels ch
WHERE ch.id IN (SELECT c.channel_id FROM im_bot_chats c WHERE c.project_id = ?1)
ORDER BY ch.created_at, ch.id
`

// Bots (channels) serving this project: purely by reverse lookup through the
// chats routed here (project -> chat -> channel). A shared bot is owner-level and
// not bound to any project, so a project only ever sees a bot through the chats
// routed to it.
func (q *Queries) ListIMBotChannelsByProject(ctx context.Context, projectID sql.NullInt64) ([]ImBotChannel, error) {
	rows, err := q.db.QueryContext(ctx, listIMBotChannelsByProject, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ImBotChannel{}
	for rows.Next() {
		var i ImBotChannel
		if err := rows.Scan(
			&i.ID,
			&i.OwnerType,
			&i.OwnerID,
			&i.CredentialFingerprint,
			&i.ChannelType,
			&i.Name,
			&i.ConnectionMode,
			&i.CredentialEnc,
			&i.WebhookSecret,
			&i.Status,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

